class LLMSetter:
    """
    Factory class to select the appropriate LLM provider.
    """

    def __init__(self, base_url, provider="generic", api_key=None):
        self.provider = provider.lower()

        if self.provider == "openai":
            self.client = OpenAIProvider(base_url, api_key)
        elif self.provider == "ollama":
            self.client = OllamaProvider(base_url)
        else:
            raise ValueError(f"Unsupported provider: {self.provider}")

    def get_model_list(self):
        return self.client.get_model_list()

    def generate_text(self, model, prompt, stream=True, temperature = 0.7):
        if stream:
            return self.client.generate_text(model, prompt, stream, temperature)
        else:
            return "".join(self.client.generate_text(model, prompt, stream, temperature))

    def test_generate_text_by_template(self,model,prompt_dict,stream = True):
        prompt = test_prompt
        for k,v in prompt_dict.items():
            prompt = prompt.replace("{" + f"{k}" + "}",v)

        return self.generate_text(model, prompt, stream = stream)
    def generate_text_by_template(self,model,template_dict,stream = True,temperature = 0.7):
        prompt = agent_prompt
        for k,v in template_dict.items():
            prompt = prompt.replace("{" + f"{k}" + "}",v)
        print(prompt)

        return self.generate_text(model, prompt, stream = stream, temperature = temperature)

    def RAG_filter_result(self,model,template_dict_list,stream = False):
        prompt = rag_prompt
        mask  = [None for i in range(len(template_dict_list))]
        for idx,template_dict in enumerate(template_dict_list):
            for k,v in template_dict.items():
                prompt = prompt.replace("{" + f"{k}" + "}",v)
            print(prompt)
            result = self.generate_text(model, prompt, stream = stream, temperature = 0)
            print(result)
            if "yes" in result:
                mask[idx] = True
            else:
                mask[idx] = False
        return mask

class EmployeeController:
    """Controller for handling employee-related operations."""

    def __init__(self):
        # Initialize a simple in-memory storage for employees
        self.employees = []
        self.next_id = 1

    def add_employee(self, employee_data):
        """Add a new employee record."""
        new_employee = {
            'id': self.next_id,
            **employee_data
        }
        self.employees.append(new_employee)
        self.next_id += 1
        return new_employee

    def _get_all_employees(self):
        """Private method to retrieve the entire list of employees."""
        return self.employees

    def getAllEmployees(self):
        """Retrieve the entire list of employees."""
        return self._get_all_employees()

    def _save_employee(self, employee):
        """Private method to save an employee to the list."""
        self.employees.append(employee)

    def saveEmployee(self, employee):
        """Save an employee to the list."""
        self._save_employee(employee)
        return {'message': 'Employee saved successfully'}

    def list_employees(self):
        """List all employee records."""
        return self.employees

    def update_employee(self, employee_id, employee_data):
        """Update an existing employee record."""
        for employee in self.employees:
            if employee['id'] == employee_id:
                employee.update(employee_data)
                return employee
        raise ValueError(f"Employee with id {employee_id} not found")

    def delete_employee(self, employee_id):
        """Delete an employee record by ID."""
        try:
            for employee in self.employees:
                if employee['id'] == employee_id:
                    self.employees.remove(employee)
                    return {'message': f'Employee with id {employee_id} deleted successfully'}
            raise ValueError(f"Employee with id {employee_id} not found")
        except ValueError as e:
            return {'error': str(e)}

    def getEmployeeById(self, employee_id):
        """Retrieve an employee by ID."""
        try:
            for employee in self.employees:
                if employee['id'] == employee_id:
                    return employee
            raise ValueError(f"Employee with id {employee_id} not found")
        except ValueError as e:
            return {'error': str(e)}

    def _find_employee_by_email(self, email):
        """Private method to find an employee by email."""
        for employee in self.employees:
            if employee.get('email') == email:
                return employee
        return None

    def getEmployeeByEmail(self, email):
        """Retrieve an employee by email."""
        employee = self._find_employee_by_email(email)
        if employee:
            return employee
        return {'error': f"Employee with email {email} not found"}

    def _sort_employees_by_last_name(self, employees):
        """Private method to sort employees by last name."""
        return sorted(employees, key=lambda e: e['name'].split()[-1])

    def getSortedEmployeesByLastName(self):
        """Retrieve all employees sorted by last name."""
        return self._sort_employees_by_last_name(self.employees)

