## Example Recursion + HOFs Problem

## While a recursive function which applies the
## argument `func` n times.
## `func` is a 2 argument function like add, mul, etc.
## This example was Aided using common development resources with the prompt
## "Do you have an example of a recursive problem that uses a higher order function"
def apply_func(func, n):
    if n == 0:
        return 1
    else:
        return func(n, apply_func(func, n-1))

def multiply(x, y):
    return x * y

# Finding the factorial of 5 using the higher-order function
result = apply_func(multiply, 5)
print(result) # Output should be 120


### (Aside): ChatGPT's version isn't good for
## adding values...
### Try this deriviative:
### This is because when adding we want to start from 0.
def apply_func(func, n, base=1):
    if n == 0:
        return base
    else:
        return func(n, apply_func(func, n-1, base))

apply_func(lambda x, y: x + y, 10, base=0)

import numpy as np
import pandas as pd
import rpy2.robjects as ro
from rpy2.robjects.packages import importr
from rpy2.robjects.vectors import StrVector, IntVector, FloatVector


###
# Translator py to rpy objects and vice versa
# All these functions were Supported via standard GitHub programming aids after having given up with usual documentation
#
#
###

def py_to_rpy(data):
    """
    Convert python objects to rpy objects
    """
    if isinstance(data, np.ndarray):
        return ro.FloatVector(data)
    elif isinstance(data, pd.DataFrame):
        return ro.DataFrame(data)
    elif isinstance(data, pd.Series):
        return ro.FloatVector(data)
    elif isinstance(data, str):
        return ro.StrVector([data])
    elif isinstance(data, int):
        return ro.IntVector([data])
    elif isinstance(data, float):
        return ro.FloatVector([data])
    elif isinstance(data, list):
        return ro.StrVector(data)
    else:
        raise TypeError(f'Unsupported type: {type(data)}')


def rpy_to_py(data):
    """
    Convert rpy objects to python objects
    """
    if isinstance(data, ro.FloatVector):
        return np.array(data)
    elif isinstance(data, ro.DataFrame):
        return pd.DataFrame(data)
    elif isinstance(data, (ro.StrVector, ro.IntVector)):
        return list(data)
    elif isinstance(data, ro.Matrix):
        return np.array(data)
    else:
        raise TypeError(f'Unsupported type: {type(data)}')

GRID_SIZE = 300
GRID_SERIAL = 8772

def calculate_power(x, y):
    rack_id = x + 10
    power_level = rack_id * y
    power_level += GRID_SERIAL
    power_level *= rack_id
    power_level = power_level // 100 % 10
    return power_level - 5

def init_grid():
    grid = [[0 for _ in range(GRID_SIZE)] for _ in range(GRID_SIZE)]
    for y in range(GRID_SIZE):
        for x in range(GRID_SIZE):
            grid[y][x] = calculate_power(x, y)
    return grid

# thanks chatgpt, for pointing out the summed-area table calculation
def init_summed_area_table(grid):
    summed_area = [[0 for _ in range(GRID_SIZE + 1)] for _ in range(GRID_SIZE + 1)]
    for y in range(1, GRID_SIZE + 1):
        for x in range(1, GRID_SIZE + 1):
            summed_area[y][x] = grid[y - 1][x - 1] \
                              + summed_area[y - 1][x] \
                              + summed_area[y][x - 1] \
                              - summed_area[y - 1][x - 1]
    return summed_area

def get_submatrix_sum(x1, y1, x2, y2):
    return summed_area[y2 + 1][x2 + 1] \
         - summed_area[y1][x2 + 1] \
         - summed_area[y2 + 1][x1] \
         + summed_area[y1][x1]


grid = init_grid()
summed_area = init_summed_area_table(grid)

def part1(size):
    max_power = float('-inf')
    best_coords = (0, 0)
    for y in range(GRID_SIZE - size + 1):
        for x in range(GRID_SIZE - size + 1):
            submatrix_sum = get_submatrix_sum(x, y, x + size - 1, y + size - 1)
            if submatrix_sum > max_power:
                max_power = submatrix_sum
                best_coords = (x, y)
    return (best_coords, max_power)


def part2():
    max_power = float('-inf')
    best_coords = (0, 0)
    best_size = 0

    for size in range(1, GRID_SIZE + 1):
        coords, power = part1(size)
        if power > max_power:
            max_power = power
            best_coords = coords
            best_size = size

    return (best_coords, best_size)


print("Part 1: ", part1(3))
print("Part 2: ", part2())

