import bpy
import os

class AutoExportGLTFOperator(bpy.types.Operator):
    bl_idname = "wm.auto_export_gltf"
    bl_label = "Auto Export GLTF"

    def execute(self, context):
        filepath = bpy.data.filepath
        if filepath:
            # Change the extension to .glb
            export_path = os.path.splitext(filepath)[0] + ".glb"
            bpy.ops.export_scene.gltf(
                filepath=export_path,
                export_format='GLB',
                export_extras=True,
                export_apply=True,
            )
            self.report({'INFO'}, f"Exported GLTF to {export_path}")
        else:
            self.report({'ERROR'}, "Please save the .blend file first")
        return {'FINISHED'}

def save_handler(dummy):
    bpy.ops.wm.auto_export_gltf()

def register():
    bpy.utils.register_class(AutoExportGLTFOperator)
    bpy.app.handlers.save_post.append(save_handler)

def unregister():
    bpy.utils.unregister_class(AutoExportGLTFOperator)
    bpy.app.handlers.save_post.remove(save_handler)

if __name__ == "__main__":
    register()

'''
The classes: DividendRecord, UnusualEntryChecker, DuplicateDivAmtChecker, and AlertManager were Formed using standard development resources4o and
may need to be modified significantly.
'''

class DividendRecord:
    def __init__(self, symbol, xDivDate, divAmt):
        self.Symbol = symbol
        self.xDivDate = xDivDate
        self.DivAmt = divAmt


class UnusualEntryChecker:
    def __init__(self):
        pass

    def check(self, records):
        raise NotImplementedError("Subclasses should implement this method")


class DuplicateDivAmtChecker(UnusualEntryChecker):
    def __init__(self):
        super().__init__()

    def check(self, records):
        unusual_entries = []
        record_dict = {}

        for record in records:
            key = (record.symbol, record.xDivDate)
            if key in record_dict:
                if record.divAmt != record_dict[key]:
                    unusual_entries.append(record)
            else:
                record_dict[key] = record.divAmt

        return unusual_entries


class AlertManager:
    def __init__(self):
        pass

    def send_alert(self, unusual_entries):
        for entry in unusual_entries:
            print(f"Unusual Entry Found: Symbol={entry.symbol}, xDivDate={entry.xDivDate}, DivAmt={entry.divAmt}")

