    return json.dumps(output)


@cbpi.step
class Flowmeter(StepBase):
    sensor = StepProperty.Sensor("Sensor")
    actorA = StepProperty.Actor("Actor")
    volume = Property.Number("Volume", configurable=True)
    resetFlowmeter = Property.Number("Reset flowmeter when done. 1 = Yes 0 = No", configurable=True, default_value="1")

    def init(self):
        if int(self.actorA) is not None:
            self.actor_on(int(self.actorA))   

    @cbpi.action("Turn Actor OFF")
    def start(self):
        if self.actorA is not None:
            self.actor_off(int(self.actorA))

    def reset(self):
        if self.actorA is not None:
            self.actor_off(int(self.actorA))

    def finish(self):
        if self.actorA is not None:
            self.actor_off(int(self.actorA))
        if self.resetFlowmeter == "1":
            for key, value in list(cbpi.cache.get("sensors").items()):
                if key == int(self.sensor):
                    value.instance.reset()

    def execute(self):
        for key, value in list(cbpi.cache.get("sensors").items()):
            if key == int(self.sensor):
                sensorValue = value.instance.getValue()
        if float(sensorValue) >= float(self.volume):
            next(self)


@cbpi.initalizer()
def init(cbpi):
    print("INITIALIZE FlOWMETER SENSOR,ACTOR AND STEP MODULE")
    cbpi.app.register_blueprint(blueprint, url_prefix='/api/flowmeter')
    print("READY")

# using the regular expression library
import re

# Lexer class to generate and return tokens
class Lexer(object):

	# Initalizing source code to the Lexer
	def __init__(self, code):
		self.code = code

	# Method used to create tokens
	def tokenize(self):

		# list to store all tokens created by the lexer
		tokens = []

		# Creating a list of words from the source code
		code = self.code.split()

		# Index of the word we are present
		code_index = 0

		# Looping throug each word in the source code to generate tokens
		while code_index < len(code):

			# Taking each word at a time and generating tokens with it
			word = code[code_index]			

			# Creating variable declaration token
			if word == "var":
				tokens.append(["VARIABLE", word])

			# Creating identifier tokens	
			elif re.match('[a-z]', word) or re.match('[A-Z]', word) and word != 'var' and word !='showme':
				if word[-1] == '.':
					tokens.append(["IDENTIFIER", word[0:len(word)-1]])
				else:
					tokens.append(["IDENTIFIER", word])

			# Creating Integer token 	
			elif re.match('[0-9]',word):
				if word[-1]=='.':
					tokens.append(["INTEGER", word[0:len(word)-1]])
				else:
					tokens.append(["INTEGER", word])

			# Creating Operator token	
			elif word in "+-*/%=@":
				tokens.append(["OPERATOR", word])

			# Token for comma
			elif word == ",":
				tokens.append(["COMMA", word])

			# Token for String
			elif '"' in word:
				if word[-1] == '.':
					tokens.append(["STRING", word[1:len(word)-2]])
				else:
					tokens.append(["STRING", word[1:len(word)-1]])

			# Statement End token
			if word == '.':
				tokens.append(["STATEMENT_END", word])
			elif word[-1] == '.':
				tokens.append(["STATEMENT_END", word[-1]])

			# Parenthesis token
			elif word in "()[]":
				tokens.append(["BRACKET",word])

			# Inout token 
			elif word == "~":
				tokens.append(["INOUT",word])

			# Increamenting token index for next word
			code_index = code_index+1

		tokens.append(["EMPTY",0])

		# Finally returning the tokens generated.
		return tokens

import os
import sys
import subprocess

project_path = os.path.join(os.path.dirname(__file__), 'vibora')

# Seeking for files pending compilation.
pending_compilation = set()
for root, dirs, files in os.walk(project_path):
    for file in files:
        if file.endswith('.pyx'):
            pending_compilation.add(os.path.join(root, file))
        elif file.endswith('.py'):
            if (file[:-3] + '.pxd') in files:
                pending_compilation.add(os.path.join(root, file))
        elif file.endswith(('.so', '.c', '.html')):
            os.remove(os.path.join(root, file))

# Calling Cython to compile our extensions.
cython = os.path.join(os.path.dirname(sys.executable), 'cython')
process = subprocess.run([cython] + list(pending_compilation) + ['--fast-fail'])
if process.returncode != 0:
    raise SystemExit(f'Failed to compile .pyx files to C.')

# Building native extensions.
process = subprocess.run(
    [
        sys.executable,
        os.path.join(os.path.dirname(project_path), 'setup.py'),
        'build_ext',
        '--inplace'
    ]
)
if process.returncode != 0:
    raise SystemExit(f'Failed to build native modules.')

print('Build process completed successfully.')

