import os
from ebooklib import epub
from bs4 import BeautifulSoup

def clean_html_to_markdown(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')

    md_lines = []

    for elem in soup.find_all(['h1', 'h2', 'h3', 'h4', 'p', 'div', 'span']):
        text = elem.get_text(strip=True)
        if not text:
            continue
        # Use Markdown-style headings
        if elem.name == 'h1':
            md_lines.append(f'# {text}')
        elif elem.name == 'h2':
            md_lines.append(f'## {text}')
        elif elem.name == 'h3':
            md_lines.append(f'### {text}')
        elif elem.name == 'h4':
            md_lines.append(f'#### {text}')
        else:
            md_lines.append(text)

    return '\n\n'.join(md_lines)

def epub_to_markdown(epub_path, output_path=os.path.join('output', 'epub.md')):
    book = epub.read_epub(epub_path)
    all_text = []

    print(f'\n📚 Total items: {len(book.items)}\n')

    for item in book.get_items():
        if item.get_name().endswith('.html') or item.get_name().endswith('.xhtml'):
            try:
                print(f'📖 Processing: {item.get_name()}')
                content = item.get_content().decode('utf-8', errors='ignore')
                md = clean_html_to_markdown(content)
                if md.strip():
                    all_text.append(md)
            except Exception as e:
                print(f'⚠️ Error reading {item.get_name()}: {e}')

    if all_text:
        full_text = '\n\n---\n\n'.join(all_text)
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(full_text)
        print(f'\n✅ Markdown file saved to: {output_path}')
    else:
        print('\n❌ No usable HTML content found in EPUB.')

epub_to_markdown(os.path.join('NASB', 'NASB New American Standard Bible (NASB).epub'))

# initially Assisted using common GitHub development utilities
class Vec2:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vec2(self.x + other.x, self.y + other.y)

    def __iadd__(self, other):
        self.x += other.x
        self.y += other.y
        return self

    def __sub__(self, other):
        return Vec2(self.x - other.x, self.y - other.y)

    def __isub__(self, other):
        self.x -= other.x
        self.y -= other.y
        return self

    def __mul__(self, other):
        return Vec2(self.x * other, self.y * other)

    def __imul__(self, other):
        self.x *= other
        self.y *= other
        return self

    def __truediv__(self, other):
        return Vec2(self.x / other, self.y / other)

    def __itruediv__(self, other):
        self.x /= other
        self.y /= other
        return self

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __ne__(self, other):
        return self.x != other.x or self.y != other.y

    def __str__(self):
        return f"({self.x}, {self.y})"

    def __repr__(self):
        return f"Vec2({self.x}, {self.y})"

    def __iter__(self):
        return iter((self.x, self.y))

    def __getitem__(self, index):
        return (self.x, self.y)[index]

    def __len__(self):
        return 2

    def __abs__(self):
        return (self.x ** 2 + self.y ** 2) ** 0.5

    def normalized(self):
        return self / abs(self)

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def cross(self, other):
        return self.x * other.y - self.y * other.x

    def angle(self, other):
        return math.acos(self.dot(other) / (abs(self) * abs(other)))

    def rotate(self, angle):
        return Vec2(
            self.x * math.cos(angle) - self.y * math.sin(angle),
            self.x * math.sin(angle) + self.y * math.cos(angle),
        )

    def lerp(self, other, t):
        return self + (other - self) * t

    def reflect(self, normal):
        return self - normal * 2 * self.dot(normal)

    def project(self, other):
        return other * (self.dot(other) / other.dot(other))

    def project_onto_unit(self, other):
        return other * self.dot(other)

    def __neg__(self):
        return Vec2(-self.x, -self.y)

    def is_zero(self):
        return self.x == 0 and self.y == 0

""" Uses exchangeratesapi.io to get exchange rates
Validation, error handling omitted for clarity.  """


import requests

def main():
    currency = get_target_currency()
    dollars = get_dollar_amount()
    converted = convert_dollars_to_target(dollars, currency)
    display_result(dollars, currency, converted)

def get_target_currency():
    """ Get target currency, and return as uppercase symbol. 
    TODO add validation, error handling """
    currency = input('Enter target currency code e.g. EUR, CAD: ')
    return currency.upper()

def get_dollar_amount():
    """ Get number of dollars.  TODO add validation, error handling """
    return float(input('Enter amount of dollars to convert: '))

def convert_dollars_to_target(dollars, target_currency):
    """ Convert amount of dollars to target currency """
    exchange_rate = get_exchange_rate(target_currency)
    converted = convert(dollars, exchange_rate)
    return converted

def get_exchange_rate(currency):
    """ Call API and extra data from response """
    response = request_rates(currency)
    rate = extract_rate(response, currency)
    return rate 

def request_rates(currency):
    """ Perform API request, return response. TODO add error handling """
    params = {'base': 'USD', 'symbols': currency}
    url = 'https://api.exchangeratesapi.io/latest'
    return requests.get(url, params=params).json()

def extract_rate(rates, currency):
    """ Process the JSON response from the API, extract rate data. TODO add error handling  """
    return rates['rates'][currency]


def convert(amount, exchange_rate):
    """ Convert using the given exchange rate """
    return amount * exchange_rate

def display_result(dollars, currency, converted):
    """ Format and display the result """
    print(f'${dollars:.2f} is equivalent to {currency} {converted:.2f}')


if __name__ == '__main__':
    main()
